    T("guest", "错。照你这个说法，一个聊天产品开了搜索功能，它就是 Agent 了？"),
    T("host", "呃……好像哪里不对。那我改一下 —— Agent 是能调用工具的大模型？"),
    T("guest", "还是错。你两次都绕着同一个词打转，就是没说出来 —— 自主。"),
    T("host", "自主……就是它自己决定调哪个工具？"),
    T("guest", "太浅。自主规划、多步执行、感知结果再调整，这才是闭环。你给它一个目标，它自己把任务拆成多步，一步步做，每一步的结果反馈回来再指导下一步。听清楚，是「反馈回来指导下一步」，不是「一口气做完」。"),
    T("host", "啊我懂了，这跟强化学习里那个感知—决策—执行的循环有点像？"),
    T("guest", "……嗯。这次方向对了。经典 AI 里叫 sense-plan-act，Agent 的闭环就是它的现代版本：感知、规划、行动、再感知。别以为我在夸你，只是这个联想恰好没错。"),
    T("host", "那我刚才那两个答法，问题是不是都出在只停在「行动」这一环，前面没规划、后面没反馈？"),
    T("guest", "总算说到点上了。工具调用只是闭环里的一个动作，不是闭环本身。"),
    T("host", "那咱们从头捋。要讲清楚 Agent 强在哪，是不是得先说普通大模型弱在哪？"),
    T("guest", "这个顺序你倒是懂。不然你说的自主是空的，没有参照物。普通大模型有三个局限，环环相扣。第一个最直观：知识被冻结。训练数据有截止日期，你问它今天的天气、最新的股价，它一无所知。"),
    T("host", "这个我熟，就像一个人毕业之后再也不看新闻，你问他今天发生了什么，他只能给你背课本。"),
    T("guest", "比喻还行，留着面试用。第二个比第一个更本质：它不能行动。你让它发邮件、查数据库、执行一段代码，它只能告诉你「你可以这样做」，自己做不到。"),
    T("host", "因为它说到底就是个文本生成器嘛，吐出来的全是字。"),
    T("guest", "对。它能给你写出一封措辞完美的邮件正文，但点那个发送按钮的事，它是真做不了的。"),
